mapper.select:
	select 


		, s.name as creator_name,u.name as auditor_name

	from app_policy_cfg a 
	left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id


    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit} and a.is_valid!=-1

	ORDER BY a.CFG_ID

	select 


		, s.name as creator_name,u.name as auditor_name

	from app_feature_index a
	left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id


    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit} and a.is_valid!=-1

	ORDER BY a.CFG_ID

	SELECT 


		, s.name as creator_name,u.name as auditor_name

	    	,dns.cfg_desc as dns_strategy_name


    FROM cfg_index_info a

    	left join dns_res_strategy dns on a.dns_strategy_id=dns.cfg_id

    left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id



    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit}
    	and a.is_valid!=-1

	ORDER BY a.CFG_ID

	SELECT 


		, s.name as creator_name,u.name as auditor_name

    FROM file_digest_cfg a
    left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id



    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit}
    	and a.is_valid!=-1

	ORDER BY a.CFG_ID

		 SELECT 

	    FROM asn_ip_cfg a 

	    	a.is_valid!=-1

	    		AND a.is_audit=#{isAudit,jdbcType=INTEGER}

	    	and a.asn_ip_group in 	

                #{groupId}

	SELECT 


		, s.name as creator_name,u.name as auditor_name

    FROM pxy_obj_trusted_ca_cert a
    left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id


    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit}
    	and a.is_valid!=-1

	ORDER BY a.CFG_ID

	SELECT 


		, s.name as creator_name,u.name as auditor_name

    FROM pxy_obj_trusted_ca_crl a
    left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id


    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit}
    	and a.is_valid!=-1
    	and (cert_id is null or cert_id == 0)

	ORDER BY a.CFG_ID

	SELECT 


		, s.name as creator_name,u.name as auditor_name

    FROM pxy_obj_keyring a
    left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id


    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit}
    	and a.is_valid!=-1

	ORDER BY a.CFG_ID

	SELECT 


