	SELECT


		, g.group_name group_1_name,s.name as creator_name,u.name as auditor_name

    FROM  dns_res_strategy a
    left join policy_group_info g on a.res_group_1_id=g.group_Id
    left join sys_user s on a.creator_id=s.id
	left join sys_user u on a.auditor_id=u.id


    		AND a.SERVICE_ID=#{serviceId,jdbcType=INTEGER}


    		AND a.function_id=#{functionId,jdbcType=INTEGER}


    		AND a.action=#{action,jdbcType=INTEGER}

    	and a.is_valid=#{isValid} and a.is_audit=#{isAudit}
