select a.cfg_id,a.cfg_desc,a.action,a.is_valid,a.is_audit,a.creator_id,a.audit_time, a.service_id,a.request_id,a.is_area_effective,a.classify,a.attribute,a.lable, a.area_effective_ids,a.function_id,a.do_log,a.user_region1,a.user_region2, a.user_region3,a.user_region4,a.user_region5,
,s.name as creator_name,u.name as auditor_name
,a.app_code,a.spec_service_id,a.behav_code
from ${tableName} a left join sys_user s on a.creator_id=s.id left join sys_user u on a.auditor_id=u.id
